// 固定真实Godot产生向量核共同RNG原语，不把本机另一实现当独立oracle。
#include "resident/storage/common_checkpoint.hpp"
#include "resident/model/common_rng.hpp"
#include <fstream>
#include <iostream>
#ifdef NDEBUG
#undef NDEBUG
#endif
#include <cassert>
using namespace hanmo::resident;
BoundaryValue read(const char* path){std::ifstream file(path);auto parsed=parse_boundary_json(std::string((std::istreambuf_iterator<char>(file)),{}));assert(parsed.ok);return std::move(parsed.value);}
Integer decimal(const BoundaryValue& row,const StableId& key){return std::stoll(boundary::get_string(row,key,"vector"));}
CodecVisitor::Buffer checkpoint(CommonState state){CodecVisitor::Buffer bytes;CodecVisitor visitor(bytes);assert(visit_common_checkpoint(visitor,state).ok&&visitor.finish().ok);return bytes;}
int main(int argc,char** argv){assert(argc==2);auto fixture=read(argv[1]);assert(boundary::get_string(fixture,"source_commit","")=="ed1daf0bf001b61586d9930840f2f1394092c079");assert(boundary::get_string(*fixture.find("engine"),"hash","")=="ed1daf0bf001b61586d9930840f2f1394092c079");assert(boundary::get_string(fixture,"format","")=="HM-GODOT-PCG32-VECTORS/1");std::size_t total=0,rejection_cases=0,zero_draws=0;for(const auto& row:boundary::array(*fixture.find("seed_rows"),"seeds"))assert(godot_pcg32_seed_state(decimal(row,"seed"))==decimal(row,"state"));auto catalog=std::make_shared<const CommonCatalog>();for(auto& row:boundary::array(*fixture.find("vectors"),"vectors")){CommonState state;state.metadata.rng_backend="godot:4.7.2-stable (official)";RngStream stream{decimal(row,"seed"),decimal(row,"before"),{"state","seed"}};state.rng.insert("world",stream);state.rng.insert("event",{77,99,{"seed","state"}});CommonStore common(state,catalog);auto result=common.random_bounded("world",boundary::get_int(row,"from","vector"),boundary::get_int(row,"to","vector"));if(!result.ok){std::cerr<<"RNG_PRIMITIVE_REJECTED "<<result.error.original.code<<"\n";return 1;}auto leaf=godot_pcg32_range(stream.state,boundary::get_int(row,"from","vector"),boundary::get_int(row,"to","vector"));assert(leaf.ok);const auto& raw=boundary::array(*row.find("raw"),"raw");assert(leaf.value.raw_draws==raw.size());auto probe=rng_detail::unsigned_bits(stream.state);for(const auto& value:raw)assert(static_cast<Integer>(rng_detail::raw(probe))==boundary::integer(value,"raw"));assert(rng_detail::signed_bits(probe)==decimal(row,"after"));if(raw.size()>1)++rejection_cases;if(raw.empty())++zero_draws;assert(result.value==boundary::get_int(row,"value","vector"));assert(common.state().rng.find("world")->state==decimal(row,"after"));assert(common.state().rng.find("world")->seed==stream.seed);assert(common.state().rng.find("world")->field_order==stream.field_order);assert(common.state().rng.find("event")->state==99);++total;}assert(total==952&&rejection_cases==87&&zero_draws==136);
 // 恢复时seed和state分别保留，抽样后clone可独立继续，撤销恢复原始字节和流顺序。
 CommonState initial;initial.metadata.rng_backend="godot:4.7.2-stable (official)";initial.rng.insert("world",{-1,0,{"state","seed"}});initial.rng.insert("event",{123,-1,{"seed","state"}});CommonStore common(initial,catalog);auto bytes=checkpoint(initial);auto save=common.begin_savepoint();assert(save.ok);for(int i=0;i<16;++i){assert(common.random_bounded("world",-1,2147483647).ok);assert(common.random_bounded("event",100,1).ok);}auto cloned=common;auto next=common.random_bounded("world",0,9999),copy_next=cloned.random_bounded("world",0,9999);assert(next.ok&&copy_next.ok&&next.value==copy_next.value&&common.state().rng.find("world")->state==cloned.state().rng.find("world")->state);assert(common.rollback_savepoint(save.value).ok&&checkpoint(common.state())==bytes);assert(checkpoint(cloned.state())!=bytes);auto commit=common.begin_savepoint();assert(commit.ok&&common.random_bounded("world",1,100).ok&&common.commit_savepoint(commit.value).ok);auto committed=checkpoint(common.state());CommonState restored;const auto& input=committed;CodecVisitor reader(input);assert(visit_common_checkpoint(reader,restored).ok&&reader.finish().ok);CommonStore resumed(restored,catalog);auto resumed_draw=resumed.random_bounded("world",-2147483648LL,2147483647),same_draw=common.random_bounded("world",-2147483648LL,2147483647);assert(resumed_draw.ok&&same_draw.ok&&resumed_draw.value==same_draw.value&&checkpoint(resumed.state())==checkpoint(common.state()));
 // 端点超出原signed32绑定不做静默窄化；未知流与未知引擎也不得消费任何状态。
 const std::pair<Integer,Integer> invalid[]={{-2147483649LL,0},{0,2147483648LL},{INT64_MIN,INT64_MAX},{2147483648LL,2147483648LL}};for(auto range:invalid){auto before=checkpoint(common.state());auto bad=common.random_bounded("world",range.first,range.second);assert(!bad.ok&&bad.error.kind==ErrorKind::unsupported_capability&&bad.error.source_id=="world"&&checkpoint(common.state())==before);}auto before=checkpoint(common.state());auto missing=common.random_bounded("missing",0,10);assert(!missing.ok&&missing.error.kind==ErrorKind::internal&&missing.error.original.code=="UnknownRandomStream"&&checkpoint(common.state())==before);common.state().metadata.rng_backend="godot:other";before=checkpoint(common.state());auto backend=common.random_bounded("world",7,7);assert(!backend.ok&&backend.error.kind==ErrorKind::unsupported_capability&&checkpoint(common.state())==before);
 std::cout<<"state_rng: PASS (952 engine vectors, 11 seed states, 87 rejection cases, 136 zero draws, clone/checkpoint/savepoint, explicit bounds/backend rejection)\n";}
